"""Models for the scoping-only site dictionary generated by canonical-naaccr.

The file is built by ``python -m canonical_naaccr.cipoc_scoping``. These models
cover the envelope, the tissue table, the staging schemas, the histology site
groups and the morphology blocks; ``tools/scoping.py`` loads and checks it.
"""

from pydantic import BaseModel, ConfigDict, Field


class TissueCodes(BaseModel):
    """One tissue's code tables."""

    codes: dict[int, dict[str, str]] = Field(
        description="Code-to-description tables keyed by NAACCR item ID. Item 400 holds the tissue's Primary Site codes.",
    )


class CodeOverride(BaseModel):
    """One item's codes in a staging schema, where they differ from NAACCR's."""

    source: str = Field(description="Key in the file's sources that the codes come from.")
    table: str | None = Field(
        default=None,
        description="Staging table the codes come from. Absent for carried-over codes.",
    )
    codes: dict[str, str] = Field(description="Description of each code or code range.")


class StagingSchema(BaseModel):
    """One CS, TNM or EOD schema: when it applies and which item codes it changes."""

    select: list[dict[str, str]] = Field(
        description="Selection rows. The schema matches when any row does, and a row matches when all of its keys do; a key the row omits matches anything.",
    )
    codes: dict[int, CodeOverride] = Field(
        description="Code overrides keyed by NAACCR item ID. An item without one keeps the NAACCR codes.",
    )


class HistologyCode(BaseModel):
    """One code/behavior pair on a site group's list."""

    term: str = Field(description="The list's abbreviated term, shown when choosing a family.")
    description: str = Field(description="The pair's v25 description, shown when choosing a code.")


class HistologyFamily(BaseModel):
    """One of a site group's 3-digit histology families."""

    label: str = Field(description="The list's label for the family, e.g. 'DUCT CARCINOMA'.")
    codes: dict[str, HistologyCode] = Field(
        description="The family's v25 code/behavior pairs on the list, keyed like '8500/3'.",
    )


class HistologySiteGroup(BaseModel):
    """One site group of the SEER Site/Histology Validation List."""

    label: str = Field(description="The list's title for the group, e.g. 'BREAST'.")
    sites: str = Field(
        description="The Primary Site codes the group covers, as comma-separated codes and ranges like a schema's select site.",
    )
    families: dict[str, HistologyFamily] = Field(
        description="The group's histology families keyed by their 3 digits. A trimmed test fixture may leave it empty.",
    )


class MorphologyBlock(BaseModel):
    """One ICD-O-3 morphology block, the fallback's unit of choice."""

    label: str = Field(description="The block's ICD-O-3 heading, e.g. 'Adenomas and adenocarcinomas'.")


class HistologyScope(BaseModel):
    """What the extractor's two histology steps offer for one case.

    Built from the scoping dictionary by ``build_histology_scope``, so the
    extractor never reads the file. It's far too large for a prompt, so prompts
    render the variable that carries it through ``prompt_variable``, which
    leaves it out.
    """

    site_group: str = Field(description="Key of the Site/Histology Validation List group for the coded Primary Site.")
    site_group_label: str = Field(description="The group's title on the list, e.g. 'BREAST'.")
    families: dict[str, str] = Field(
        description="The family step's choices: each 3-digit family's label and its members' abbreviated terms.",
    )
    family_codes: dict[str, dict[str, str]] = Field(
        description="Each family's code/behavior pairs with their v25 descriptions, for the code step.",
    )
    blocks: dict[str, str] = Field(
        description="The fallback's choices: each ICD-O-3 morphology block's heading, keyed by its 3-digit range.",
    )
    block_codes: dict[str, dict[str, str]] = Field(
        description="Each block's v25 code/behavior pairs with their descriptions, for the fallback's code step.",
    )

    def listed(self, pair: str) -> bool:
        """Whether the site group lists the code/behavior pair, like '8500/3'."""
        return any(pair in codes for codes in self.family_codes.values())


class ScopingDictionary(BaseModel):
    """The scoping-only site dictionary.

    Sections not modeled yet (algorithms, items) are ignored, so a file from a
    newer generator still loads.
    """

    model_config = ConfigDict(extra="ignore")

    sources: dict[str, str] = Field(
        description="Source and version of each reference the file is built from, e.g. eod: 'eod_public 3.3'.",
    )
    tissues: dict[str, TissueCodes] = Field(
        description="Code tables for each GrossSite tissue other than 'unspecified'.",
    )
    schemas: dict[str, StagingSchema] = Field(
        description="Staging schemas keyed <algorithm>/<schema_id>, in the generator's order.",
    )
    histology: dict[str, HistologySiteGroup] = Field(
        description="Site groups of the SEER Site/Histology Validation List, keyed by the snake_case of their titles. Together they cover every Primary Site code once.",
    )
    blocks: dict[str, MorphologyBlock] = Field(
        description="ICD-O-3 morphology blocks keyed by the 3-digit range they cover, e.g. '814-838'.",
    )
